"""Invoice retry policy."""

from dataclasses import dataclass
from pathlib import Path

try:
    import tomllib
except ModuleNotFoundError:  # pragma: no cover - Python < 3.11
    import tomli as tomllib  # type: ignore[no-redef]


@dataclass(frozen=True)
class InvoiceRetryPolicy:
    initial_delay_seconds: int
    max_attempts: int
    backoff_multiplier: int


def load_invoice_retry_policy() -> InvoiceRetryPolicy:
    raw = _load_invoice_retry_section()
    return InvoiceRetryPolicy(
        initial_delay_seconds=raw.get("initial_delay_seconds", 30),
        max_attempts=raw.get("max_attempts", 5),
        backoff_multiplier=raw.get("backoff_multiplier", 2),
    )


def _load_invoice_retry_section() -> dict:
    path = Path("configs") / "retry_policy.toml"
    if not path.is_file():
        return {}
    with path.open("rb") as file:
        data = tomllib.load(file)
    return data.get("invoice_retry", {})
